import mongoose, { Schema } from "mongoose";
const packageSchema = new Schema({
    title: {
        type: String,
        required: true,
        trim: true,
    },
    description: {
        type: String,
        required: true,
        trim: true,
    },
    availableSlots: {
        type: Number,
        required: true,
        min: 0,
    },
    price: {
        type: Number,
        required: true,
        min: 0,
    },
}, {
    timestamps: true,
});
const Package = mongoose.model("Package", packageSchema);
export default Package;
